import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, seq, active
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, limit_price, qty):
        # side is side of incoming order
        # returns remaining qty after matching
        if side == 'buy':
            while qty > 0:
                clean_sell()
                if not sell_heap:
                    break
                price, seq, oid = sell_heap[0]
                if limit_price is not None and price > limit_price:
                    break
                resting = book[oid]
                trade_qty = min(qty, resting['qty'])
                trades.append([None, oid, price, trade_qty])  # placeholder buy_id filled by caller
                resting['qty'] -= trade_qty
                qty -= trade_qty
                if resting['qty'] == 0:
                    resting['active'] = False
                    heapq.heappop(sell_heap)
        else:
            while qty > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, seq, oid = buy_heap[0]
                price = -negprice
                if limit_price is not None and price < limit_price:
                    break
                resting = book[oid]
                trade_qty = min(qty, resting['qty'])
                trades.append([oid, None, price, trade_qty])  # placeholder sell_id filled by caller
                resting['qty'] -= trade_qty
                qty -= trade_qty
                if resting['qty'] == 0:
                    resting['active'] = False
                    heapq.heappop(buy_heap)
        return qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            start_trade_idx = len(trades)
            remaining = match_incoming(side, price, qty)
            # fill in the incoming id in trades from this call
            for i in range(start_trade_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid
            if remaining > 0:
                seq_counter += 1
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                # fully filled, mark as inactive placeholder so cancel does nothing
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            start_trade_idx = len(trades)
            remaining = match_incoming(side, price, qty)
            for i in range(start_trade_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid
            # discard remainder, mark id as done
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            start_trade_idx = len(trades)
            remaining = match_incoming(side, None, qty)
            for i in range(start_trade_idx, len(trades)):
                t = trades[i]
                if side == 'buy':
                    t[0] = oid
                else:
                    t[1] = oid
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': -1, 'active': False}

    return trades

